<?php
namespace App\Models;
use Illuminate\Foundation\Auth\User as Authenticatable;
use Illuminate\Notifications\Notifiable;
class User extends Authenticatable { use Notifiable; protected $fillable=["name","email","password","bio","avatar","cover","location","website","phone"]; protected $hidden=["password","remember_token"]; protected function casts(): array { return ["email_verified_at"=>"datetime","password"=>"hashed","last_seen_at"=>"datetime"]; } public function posts(){return $this->hasMany(Post::class);} public function comments(){return $this->hasMany(Comment::class);} public function likes(){return $this->hasMany(Like::class);} public function savedPosts(){return $this->hasMany(SavedPost::class);} public function friendships(){return $this->hasMany(Friendship::class,"sender_id");} public function receivedFriendships(){return $this->hasMany(Friendship::class,"receiver_id");} public function isOnline(){return $this->last_seen_at && $this->last_seen_at->gt(now()->subMinutes(5));} }
